from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError
from robot.running import EXECUTION_CONTEXTS
from taf.ul.ettf.object_provider.utils import log_created, log_already_created
from ute_tshark import ute_tshark
from ute_fsmaccess import ute_fsmaccess
from ute_pdu import ute_pdu
from abc import ABCMeta, abstractmethod
try:
    from ute_wtssim import WTSsim as ute_wtssim
except ImportError:
    from ute_wtssim import ute_wtssim as ute_wtssim


def get_current_suite():
    return EXECUTION_CONTEXTS.current.suite


def get_current_testcase():
    return '{} {}'.format(get_current_suite(), EXECUTION_CONTEXTS.current.test)


class Creator:
    __metaclass__ = ABCMeta

    @abstractmethod
    def create(self, obj, object_type):
        pass


class OneTime(Creator):
    def create(self, obj, object_type):
        if not obj.instance:
            obj.instance = object_type()
            log_created(object_type, obj)
        else:
            log_already_created(object_type, obj)
        return obj.instance


class Scope(Creator):
    def __init__(self, scope_name):
        self.scope_name = scope_name
        super(Scope, self).__init__()

    def create(self, obj, object_type):
        if not obj.instance or self.scope_name != obj.scope_name:
            obj.instance = object_type()
            obj.scope_name = self.scope_name
            log_created(object_type, obj)
        else:
            log_already_created(object_type, obj)
        return obj.instance


class RobotLibraryScope(Creator):
    def __init__(self, obj_name):
        self.obj_name = obj_name
        super(RobotLibraryScope, self).__init__()

    def create(self, obj, object_type):
        try:
            return BuiltIn().get_library_instance(self.obj_name)
        except (RuntimeError, RobotNotRunningError):
            pass

        if hasattr(object_type, 'ROBOT_LIBRARY_SCOPE'):
            scope = object_type.ROBOT_LIBRARY_SCOPE.lower()
            if scope == 'global':
                return OneTime().create(obj, object_type)
            elif scope in ('test suite', 'suite'):
                return Scope(get_current_suite()).create(obj, object_type)
        return Scope(get_current_testcase()).create(obj, object_type)


# Object type mapped to it's creator instance.
creation_policy_map = {
    ute_wtssim: RobotLibraryScope('ute_wtssim'),
    ute_tshark: RobotLibraryScope('ute_tshark'),
    ute_fsmaccess: RobotLibraryScope('ute_fsmaccess'),
    ute_pdu: RobotLibraryScope('ute_pdu'),
}


class ObjectProvider(object):

    class ScopeObject(object):
        def __init__(self, instance=None, scope_name=None):
            self.instance = instance
            self.scope_name = scope_name

    def __init__(self):
        self.egate = ObjectProvider.ScopeObject()
        self.tshark = ObjectProvider.ScopeObject()
        self.fsmaccess = ObjectProvider.ScopeObject()
        self.pdu = ObjectProvider.ScopeObject()

    @staticmethod
    def _create(object_type, obj):
        return creation_policy_map[object_type].create(obj, object_type)

    def get_egate(self):
        return self._create(ute_wtssim, self.egate)

    def get_tshark(self):
        return self._create(ute_tshark, self.tshark)

    def get_fsmaccess(self):
        return self._create(ute_fsmaccess, self.fsmaccess)

    def get_pdu(self):
        return self._create(ute_pdu, self.pdu)


provider = ObjectProvider()
